@Component
public class ContentEventListener {
    private final StringRedisTemplate redis;
    private final ProcessedMessageRepository processed;

    public ContentEventListener(StringRedisTemplate redis, ProcessedMessageRepository processed) {
        this.redis = redis;
        this.processed = processed;
    }

    @RabbitListener(queues = "topic.cache.evict")
    public void onContentUpdated(ContentUpdatedEvent event, Channel channel,
                                 @Header(AmqpHeaders.DELIVERY_TAG) long tag) throws IOException {
        try {
            String id = event.messageId();
            if (Boolean.TRUE.equals(redis.opsForValue()
                    .setIfAbsent("mq:dedup:" + id, "1", Duration.ofHours(24)))) {
                redis.delete("topic:slug:" + event.slug());
                processed.save(new ProcessedMessage(id));
            }
            channel.basicAck(tag, false);
        } catch (Exception e) {
            channel.basicNack(tag, false, false);
        }
    }
}

@Service
public class ContentEventPublisher {
    private static final Logger log = LoggerFactory.getLogger(ContentEventPublisher.class);
    private final RabbitTemplate rabbitTemplate;

    public ContentEventPublisher(RabbitTemplate rabbitTemplate) {
        this.rabbitTemplate = rabbitTemplate;
        this.rabbitTemplate.setMandatory(true);
        this.rabbitTemplate.setConfirmCallback((correlation, ack, cause) -> {
            if (!ack) {
                String id = correlation == null ? "-" : correlation.getId();
                log.warn("消息未被 broker 接收: {} {}", id, cause);
            }
        });
    }

    public void publish(ContentUpdatedEvent event) {
        CorrelationData correlation = new CorrelationData(event.messageId());
        rabbitTemplate.convertAndSend("content.topic", "content.updated." + event.type(),
                event, correlation);
    }
}
